'use client'

import { useEffect, useId, useRef, useState } from 'react'
import type { CSSProperties, PointerEvent, ReactNode } from 'react'
import './scratch-reveal.css'

export interface ScratchRevealProps {
  /** Artwork remains hidden from assistive technology and interaction until revealed. */
  children: ReactNode
  label?: string
  coverText?: string
  coverColor?: string
  brushSize?: number
  threshold?: number
  onReveal?: () => void
  className?: string
}

type ScratchPoint = { x: number; y: number }
type ScratchStroke = { points: ScratchPoint[]; radius: number }

/** A scratchable, locally drawn foil with a complete keyboard alternative. */
export function ScratchReveal({
  children,
  label = 'Scratch to reveal',
  coverText = 'A little curiosity pays off',
  coverColor = '#bdc4bd',
  brushSize = 36,
  threshold = 0.45,
  onReveal,
  className = '',
}: ScratchRevealProps) {
  const instanceId = useId()
  const canvasRef = useRef<HTMLCanvasElement>(null)
  const stageRef = useRef<HTMLDivElement>(null)
  const strokesRef = useRef<ScratchStroke[]>([])
  const pointerRef = useRef<number | null>(null)
  const revealedRef = useRef(false)
  const callbackRef = useRef(onReveal)
  const lastCheckRef = useRef(0)
  const drawRef = useRef<() => void>(() => {})
  const [revealed, setRevealed] = useState(false)
  const [ready, setReady] = useState(false)
  const brush = Number.isFinite(brushSize) ? Math.max(8, Math.min(140, brushSize)) : 36
  const target = Number.isFinite(threshold) ? Math.max(0.05, Math.min(1, threshold)) : 0.45

  useEffect(() => { callbackRef.current = onReveal }, [onReveal])

  useEffect(() => {
    const stage = stageRef.current
    const canvas = canvasRef.current
    const context = canvas?.getContext('2d', { willReadFrequently: true })
    if (!stage || !canvas || !context) return

    function draw() {
      if (!stage || !canvas || !context) return
      const { width, height } = stage.getBoundingClientRect()
      if (width <= 0 || height <= 0) return
      const ratio = Math.min(window.devicePixelRatio || 1, 2)
      canvas.width = Math.ceil(width * ratio)
      canvas.height = Math.ceil(height * ratio)
      context.setTransform(ratio, 0, 0, ratio, 0, 0)
      context.globalCompositeOperation = 'source-over'
      context.fillStyle = coverColor
      context.fillRect(0, 0, width, height)
      // The foil is generated locally; no images or cross-origin pixel reads.
      context.strokeStyle = 'rgba(255,255,255,.19)'
      context.lineWidth = 1
      for (let line = -height; line < width; line += 8) {
        context.beginPath()
        context.moveTo(line, 0)
        context.lineTo(line + height, height)
        context.stroke()
      }
      context.fillStyle = 'rgba(20,35,26,.1)'
      for (let index = 0; index < 700; index += 1) {
        const x = ((index * 73 + 19) % 997) / 997 * width
        const y = ((index * 137 + 47) % 991) / 991 * height
        context.fillRect(x, y, 1, 1)
      }
      context.fillStyle = 'rgba(21,36,27,.8)'
      context.textAlign = 'center'
      context.textBaseline = 'middle'
      context.font = '500 10px system-ui, sans-serif'
      context.fillText('A SMALL DISCOVERY', width / 2, height / 2 - 46)
      context.font = `500 ${Math.min(29, width / 12)}px Georgia, serif`
      const words = coverText.split(/\s+/)
      const lines: string[] = []
      let current = ''
      for (const word of words) {
        const next = current ? `${current} ${word}` : word
        if (current && context.measureText(next).width > width - 48) {
          lines.push(current)
          current = word
        } else current = next
      }
      if (current) lines.push(current)
      const visibleLines = lines.slice(0, 3)
      visibleLines.forEach((line, index) => context.fillText(line, width / 2, height / 2 + (index - (visibleLines.length - 1) / 2) * 30, width - 32))
      context.font = '400 10px system-ui, sans-serif'
      context.fillText('SCRATCH THE SURFACE', width / 2, height / 2 + 58)
      context.globalCompositeOperation = 'destination-out'
      context.lineCap = 'round'
      context.lineJoin = 'round'
      for (const stroke of strokesRef.current) {
        context.lineWidth = stroke.radius * Math.min(width, height) * 2
        context.beginPath()
        stroke.points.forEach((point, index) => {
          if (index === 0) context.moveTo(point.x * width, point.y * height)
          else context.lineTo(point.x * width, point.y * height)
        })
        if (stroke.points.length === 1) {
          const point = stroke.points[0]
          context.lineTo(point.x * width + 0.01, point.y * height + 0.01)
        }
        context.stroke()
      }
      setReady(true)
    }
    drawRef.current = draw
    draw()
    const observer = new ResizeObserver(draw)
    observer.observe(stage)
    return () => {
      observer.disconnect()
      drawRef.current = () => {}
      pointerRef.current = null
    }
  }, [coverColor, coverText])

  function reveal() {
    if (revealedRef.current) return
    revealedRef.current = true
    const captured = pointerRef.current
    pointerRef.current = null
    if (captured !== null && canvasRef.current?.hasPointerCapture(captured)) canvasRef.current.releasePointerCapture(captured)
    setRevealed(true)
    callbackRef.current?.()
  }

  function checkCoverage(force = false) {
    if (!force && performance.now() - lastCheckRef.current < 140) return
    lastCheckRef.current = performance.now()
    const canvas = canvasRef.current
    const context = canvas?.getContext('2d')
    if (!canvas || !context || canvas.width === 0 || canvas.height === 0) return
    const pixels = context.getImageData(0, 0, canvas.width, canvas.height).data
    let clear = 0
    let total = 0
    // Sample the same evenly spaced grid at every density and viewport size.
    for (let y = 0; y < 48; y += 1) {
      for (let x = 0; x < 64; x += 1) {
        const px = Math.min(canvas.width - 1, Math.floor((x + 0.5) / 64 * canvas.width))
        const py = Math.min(canvas.height - 1, Math.floor((y + 0.5) / 48 * canvas.height))
        if (pixels[(py * canvas.width + px) * 4 + 3] < 80) clear += 1
        total += 1
      }
    }
    if (clear / total >= target) reveal()
  }

  function point(event: PointerEvent<HTMLCanvasElement>): ScratchPoint {
    const bounds = event.currentTarget.getBoundingClientRect()
    return { x: (event.clientX - bounds.left) / Math.max(1, bounds.width), y: (event.clientY - bounds.top) / Math.max(1, bounds.height) }
  }

  function paint(event: PointerEvent<HTMLCanvasElement>, first = false) {
    const canvas = event.currentTarget
    const context = canvas.getContext('2d')
    if (!context) return
    const bounds = canvas.getBoundingClientRect()
    const next = point(event)
    if (first) strokesRef.current.push({ points: [], radius: brush / 2 / Math.max(1, Math.min(bounds.width, bounds.height)) })
    const stroke = strokesRef.current[strokesRef.current.length - 1]
    if (!stroke) return
    const previous = stroke.points[stroke.points.length - 1] ?? next
    stroke.points.push(next)
    context.globalCompositeOperation = 'destination-out'
    context.lineWidth = stroke.radius * Math.min(bounds.width, bounds.height) * 2
    context.lineCap = 'round'
    context.lineJoin = 'round'
    context.beginPath()
    context.moveTo(previous.x * bounds.width, previous.y * bounds.height)
    context.lineTo(next.x * bounds.width + (first ? 0.01 : 0), next.y * bounds.height + (first ? 0.01 : 0))
    context.stroke()
    checkCoverage()
  }

  function endScratch(event: PointerEvent<HTMLCanvasElement>) {
    if (pointerRef.current !== event.pointerId) return
    pointerRef.current = null
    if (event.currentTarget.hasPointerCapture(event.pointerId)) event.currentTarget.releasePointerCapture(event.pointerId)
    checkCoverage(true)
  }

  function reset() {
    revealedRef.current = false
    pointerRef.current = null
    strokesRef.current = []
    drawRef.current()
    setRevealed(false)
  }

  return (
    <div className={`ac-scratch-reveal ${className}`.trim()} data-revealed={revealed} data-ready={ready} style={{ '--ac-scratch-cover': coverColor } as CSSProperties}>
      <div className="ac-scratch-stage" ref={stageRef}>
        <div className="ac-scratch-artwork" id={`${instanceId}-artwork`} aria-hidden={!revealed} ref={(element) => { if (element) element.inert = !revealed }}>
          {children}
        </div>
        <div className="ac-scratch-fallback" aria-hidden="true">{coverText}</div>
        <canvas
          className="ac-scratch-canvas"
          ref={canvasRef}
          aria-hidden="true"
          onPointerDown={(event) => {
            if (!event.isPrimary || event.button !== 0 || revealedRef.current) return
            pointerRef.current = event.pointerId
            event.currentTarget.setPointerCapture(event.pointerId)
            paint(event, true)
          }}
          onPointerMove={(event) => { if (pointerRef.current === event.pointerId) paint(event) }}
          onPointerUp={endScratch}
          onPointerCancel={endScratch}
          onLostPointerCapture={endScratch}
        />
      </div>
      <div className="ac-scratch-footer">
        <span className="ac-scratch-label" aria-live="polite">{revealed ? 'Discovery complete' : label}</span>
        <button type="button" className="ac-scratch-button" aria-controls={`${instanceId}-artwork`} onClick={revealed ? reset : reveal}>
          {revealed ? 'Reset artwork' : 'Reveal artwork'}<span aria-hidden="true">{revealed ? '↺' : '↗'}</span>
        </button>
      </div>
    </div>
  )
}

.ac-scratch-reveal,
.ac-scratch-reveal * { box-sizing: border-box; }
.ac-scratch-reveal {
  position: relative;
  display: grid;
  grid-template-rows: minmax(0, 1fr) auto;
  width: 100%;
  height: var(--ac-scratch-height, 300px);
  min-height: 230px;
  isolation: isolate;
  overflow: hidden;
  background: var(--ac-scratch-paper, #f2f0e7);
  color: var(--ac-scratch-ink, #26372b);
  border: 1px solid var(--ac-scratch-border, rgb(38 55 43 / 14%));
  border-radius: var(--ac-scratch-radius, 8px);
}
.ac-scratch-stage { position: relative; overflow: hidden; min-height: 0; }
.ac-scratch-artwork,
.ac-scratch-canvas,
.ac-scratch-fallback { position: absolute; inset: 0; width: 100%; height: 100%; }
.ac-scratch-artwork { pointer-events: none; user-select: none; overflow: hidden; }
.ac-scratch-reveal[data-revealed="true"] .ac-scratch-artwork { pointer-events: auto; user-select: auto; }
.ac-scratch-canvas { display: block; cursor: crosshair; touch-action: none; opacity: 1; transition: opacity 260ms ease; }
.ac-scratch-fallback { display: grid; place-items: center; padding: 30px; background: var(--ac-scratch-cover, #bdc4bd); text-align: center; font: 26px Georgia, serif; }
.ac-scratch-reveal[data-ready="true"] .ac-scratch-fallback { display: none; }
.ac-scratch-reveal[data-revealed="true"] .ac-scratch-canvas,
.ac-scratch-reveal[data-revealed="true"] .ac-scratch-fallback { pointer-events: none; opacity: 0; }
.ac-scratch-footer { position: relative; z-index: 1; display: flex; min-height: 56px; padding: 6px 10px 6px 16px; align-items: center; justify-content: space-between; gap: 12px; background: var(--ac-scratch-paper, #f2f0e7); border-top: 1px solid var(--ac-scratch-border, rgb(38 55 43 / 14%)); }
.ac-scratch-label { font: 500 10px/1.4 system-ui, sans-serif; letter-spacing: .02em; }
.ac-scratch-button { display: inline-flex; min-height: 44px; align-items: center; justify-content: center; gap: 12px; flex-shrink: 0; padding: 10px 12px; border: 1px solid currentColor; border-radius: 999px; background: transparent; color: inherit; font: 500 10px/1.2 system-ui, sans-serif; cursor: pointer; }
.ac-scratch-button span { font-size: 18px; }
.ac-scratch-button:hover { background: rgb(38 55 43 / 6%); }
.ac-scratch-button:focus-visible { outline: 2px solid currentColor; outline-offset: 3px; }
@media (prefers-reduced-motion: reduce) { .ac-scratch-canvas { transition: none; } }

'use client'

import { useEffect, useRef, useState } from 'react'
import type { CSSProperties, ReactNode } from 'react'
import './pixel-swap.css'

export type PixelSwapSide = 'front' | 'back'

export interface PixelSwapProps {
  /** Decorative artwork only; controls inside either face are intentionally inert. */
  front: ReactNode
  back: ReactNode
  frontLabel?: string
  backLabel?: string
  columns?: number
  rows?: number
  duration?: number
  onValueChange?: (side: PixelSwapSide) => void
  className?: string
}

type Phase = 'idle' | 'covering' | 'clearing'

function clampInteger(value: number, fallback: number, min: number, max: number) {
  return Number.isFinite(value) ? Math.max(min, Math.min(max, Math.round(value))) : fallback
}

/** A deterministic pixel curtain that changes artwork only when completely covered. */
export function PixelSwap({
  front,
  back,
  frontLabel = 'First artwork',
  backLabel = 'Second artwork',
  columns = 8,
  rows = 6,
  duration = 800,
  onValueChange,
  className = '',
}: PixelSwapProps) {
  const [side, setSide] = useState<PixelSwapSide>('front')
  const [phase, setPhase] = useState<Phase>('idle')
  const sideRef = useRef<PixelSwapSide>('front')
  const targetRef = useRef<PixelSwapSide>('front')
  const busyRef = useRef(false)
  const reducedRef = useRef(false)
  const timersRef = useRef<ReturnType<typeof setTimeout>[]>([])
  const callbackRef = useRef(onValueChange)
  const columnCount = clampInteger(columns, 8, 2, 20)
  const rowCount = clampInteger(rows, 6, 2, 16)
  const timing = Number.isFinite(duration) ? Math.max(240, Math.min(3000, duration)) : 800
  // Freeze transition geometry until the current curtain finishes.
  const [transition, setTransition] = useState({ columns: columnCount, rows: rowCount, duration: timing })
  const visibleColumns = phase === 'idle' ? columnCount : transition.columns
  const visibleRows = phase === 'idle' ? rowCount : transition.rows
  const visibleDuration = phase === 'idle' ? timing : transition.duration

  useEffect(() => { callbackRef.current = onValueChange }, [onValueChange])

  function clearTimers() {
    timersRef.current.forEach(clearTimeout)
    timersRef.current = []
  }

  function commitSide(next: PixelSwapSide) {
    if (sideRef.current === next) return
    sideRef.current = next
    setSide(next)
    callbackRef.current?.(next)
  }

  useEffect(() => {
    const media = window.matchMedia('(prefers-reduced-motion: reduce)')
    function updateMotion() {
      reducedRef.current = media.matches
      if (media.matches && busyRef.current) {
        clearTimers()
        commitSide(targetRef.current)
        busyRef.current = false
        setPhase('idle')
      }
    }
    updateMotion()
    media.addEventListener('change', updateMotion)
    return () => {
      media.removeEventListener('change', updateMotion)
      clearTimers()
      busyRef.current = false
    }
  }, [])

  function swap() {
    if (busyRef.current) return
    const next = sideRef.current === 'front' ? 'back' : 'front'
    targetRef.current = next
    if (reducedRef.current) {
      commitSide(next)
      return
    }
    busyRef.current = true
    setTransition({ columns: columnCount, rows: rowCount, duration: timing })
    setPhase('covering')
    timersRef.current = [
      setTimeout(() => {
        commitSide(next)
        setPhase('clearing')
      }, timing * 0.48),
      setTimeout(() => {
        timersRef.current = []
        busyRef.current = false
        setPhase('idle')
      }, timing),
    ]
  }

  const currentLabel = side === 'front' ? frontLabel : backLabel
  const style = {
    '--ac-pixel-columns': visibleColumns,
    '--ac-pixel-rows': visibleRows,
    '--ac-pixel-cell-duration': `${visibleDuration * 0.24}ms`,
  } as CSSProperties

  return (
    <div className={`ac-pixel-swap ${className}`.trim()} style={style} data-phase={phase} data-side={side}>
      <div className="ac-pixel-stage">
        <div className="ac-pixel-face" hidden={side !== 'front'} role="img" aria-label={frontLabel}>
          <div aria-hidden="true" ref={(element) => { if (element) element.inert = true }}>{front}</div>
        </div>
        <div className="ac-pixel-face" hidden={side !== 'back'} role="img" aria-label={backLabel}>
          <div aria-hidden="true" ref={(element) => { if (element) element.inert = true }}>{back}</div>
        </div>
        <div className="ac-pixel-grid" aria-hidden="true">
          {Array.from({ length: visibleColumns * visibleRows }, (_, index) => {
            const x = index % visibleColumns
            const y = Math.floor(index / visibleColumns)
            const order = (x / (visibleColumns - 1) + (visibleRows - 1 - y) / (visibleRows - 1)) / 2
            return <span key={index} className="ac-pixel-cell" data-tone={(x + y) % 3} style={{ '--ac-pixel-delay': `${order * visibleDuration * 0.22}ms` } as CSSProperties} />
          })}
        </div>
      </div>
      <div className="ac-pixel-footer">
        <span className="ac-pixel-label" aria-live="polite" aria-atomic="true">{currentLabel}</span>
        <button type="button" className="ac-pixel-button" onClick={swap} aria-disabled={phase !== 'idle'}>
          <span>Swap artwork</span><span aria-hidden="true">⇄</span>
        </button>
      </div>
    </div>
  )
}

.ac-pixel-swap,
.ac-pixel-swap * { box-sizing: border-box; }
.ac-pixel-swap {
  display: grid;
  grid-template-rows: minmax(0, 1fr) auto;
  position: relative;
  width: 100%;
  height: var(--ac-pixel-height, 300px);
  min-height: 230px;
  overflow: hidden;
  isolation: isolate;
  background: var(--ac-pixel-paper, #e8e4d9);
  color: var(--ac-pixel-ink, #34352d);
  border: 1px solid var(--ac-pixel-border, rgb(52 53 45 / 14%));
  border-radius: var(--ac-pixel-radius, 8px);
}
.ac-pixel-stage { position: relative; min-height: 0; overflow: hidden; }
.ac-pixel-face,
.ac-pixel-face > div,
.ac-pixel-grid { position: absolute; inset: 0; width: 100%; height: 100%; }
.ac-pixel-face { pointer-events: none; user-select: none; overflow: hidden; }
.ac-pixel-face[hidden] { display: none; }
.ac-pixel-grid { display: grid; grid-template-columns: repeat(var(--ac-pixel-columns), minmax(0, 1fr)); grid-template-rows: repeat(var(--ac-pixel-rows), minmax(0, 1fr)); pointer-events: none; }
.ac-pixel-cell { display: block; min-width: 0; min-height: 0; background: var(--ac-pixel-curtain, #e95c3c); transform: scale(0); }
.ac-pixel-cell[data-tone="1"] { background: var(--ac-pixel-curtain-secondary, var(--ac-pixel-curtain, #e95c3c)); }
.ac-pixel-cell[data-tone="2"] { background: var(--ac-pixel-curtain-tertiary, var(--ac-pixel-curtain, #e95c3c)); }
.ac-pixel-swap[data-phase="covering"] .ac-pixel-cell { transform: scale(1.04); transition: transform var(--ac-pixel-cell-duration) cubic-bezier(.6, 0, .2, 1) var(--ac-pixel-delay); }
.ac-pixel-swap[data-phase="clearing"] .ac-pixel-cell { transform: scale(0); transition: transform var(--ac-pixel-cell-duration) cubic-bezier(.6, 0, .2, 1) var(--ac-pixel-delay); }
.ac-pixel-footer { position: relative; z-index: 1; display: flex; min-height: 56px; align-items: center; justify-content: space-between; gap: 12px; padding: 6px 10px 6px 16px; border-top: 1px solid var(--ac-pixel-border, rgb(52 53 45 / 14%)); background: var(--ac-pixel-paper, #e8e4d9); }
.ac-pixel-label { font: 500 10px/1.4 system-ui, sans-serif; overflow-wrap: anywhere; }
.ac-pixel-button { display: inline-flex; min-height: 44px; align-items: center; justify-content: center; gap: 12px; flex-shrink: 0; padding: 10px 12px; border: 1px solid currentColor; border-radius: 999px; background: transparent; color: inherit; font: 500 10px/1.2 system-ui, sans-serif; cursor: pointer; }
.ac-pixel-button > span:last-child { font-size: 22px; line-height: 1; }
.ac-pixel-button:hover { background: rgb(52 53 45 / 6%); }
.ac-pixel-button:focus-visible { outline: 2px solid currentColor; outline-offset: 3px; }
.ac-pixel-button[aria-disabled="true"] { cursor: progress; }
@media (prefers-reduced-motion: reduce) { .ac-pixel-cell { transition: none !important; } }

'use client'

import { useEffect, useId, useRef, useState } from 'react'
import type { CSSProperties, ReactNode } from 'react'
import './ripple-field.css'

export interface RippleFieldProps {
  children?: ReactNode
  label?: string
  color?: string
  /** The number of rings kept in the pool, clamped from 1 to 24. */
  maxRipples?: number
  className?: string
}

interface Ripple { id: number; x: number; y: number; angle: number; expires: number }
interface Point { x: number; y: number; time: number }

const controls = 'a, button, input, select, textarea, summary, [role="button"], [role="slider"], [contenteditable]:not([contenteditable="false"])'
const manualPositions = [[0.5, 0.5], [0.33, 0.42], [0.7, 0.61], [0.6, 0.3], [0.3, 0.68]]

function isControl(target: EventTarget | null) {
  return target instanceof Element && !!target.closest(controls)
}

/** A still surface that responds with finite, overlapping rings. */
export function RippleField({ children, label = 'Ripple field', color = '#a7c6dd', maxRipples = 12, className = '' }: RippleFieldProps) {
  const instructionsId = useId()
  const field = useRef<HTMLDivElement>(null)
  const sequence = useRef(0)
  const manualSequence = useRef(0)
  const frame = useRef<number | null>(null)
  const pending = useRef<Point | null>(null)
  const previous = useRef<Point | null>(null)
  const tapStart = useRef<(Point & { pointerId: number }) | null>(null)
  const finePointer = useRef(false)
  const reducedMotion = useRef(false)
  const [ripples, setRipples] = useState<Ripple[]>([])
  const [status, setStatus] = useState('')
  const safeMax = Number.isFinite(maxRipples) ? Math.max(1, Math.min(24, Math.round(maxRipples))) : 12

  function resetPointer() {
    if (frame.current !== null) cancelAnimationFrame(frame.current)
    frame.current = null
    pending.current = null
    previous.current = null
  }

  useEffect(() => {
    const motionQuery = window.matchMedia('(prefers-reduced-motion: reduce)')
    const pointerQuery = window.matchMedia('(hover: hover) and (pointer: fine)')
    function updatePreferences() {
      reducedMotion.current = motionQuery.matches
      finePointer.current = pointerQuery.matches && !motionQuery.matches
      resetPointer()
      setRipples([])
    }
    function visibilityChanged() {
      if (document.hidden) resetPointer()
    }
    updatePreferences()
    motionQuery.addEventListener('change', updatePreferences)
    pointerQuery.addEventListener('change', updatePreferences)
    document.addEventListener('visibilitychange', visibilityChanged)
    return () => {
      resetPointer()
      motionQuery.removeEventListener('change', updatePreferences)
      pointerQuery.removeEventListener('change', updatePreferences)
      document.removeEventListener('visibilitychange', visibilityChanged)
    }
  }, [])

  useEffect(() => {
    setRipples((current) => current.length > safeMax ? current.slice(-safeMax) : current)
  }, [safeMax])

  useEffect(() => {
    if (!ripples.length) return
    const nextExpiry = Math.min(...ripples.map((ripple) => ripple.expires))
    const timer = window.setTimeout(() => {
      setRipples((current) => current.filter((ripple) => ripple.expires > performance.now()))
    }, Math.max(16, nextExpiry - performance.now()))
    return () => window.clearTimeout(timer)
  }, [ripples])

  function addRipple(x: number, y: number, announce = false) {
    const id = sequence.current++
    const now = performance.now()
    const ripple = {
      id,
      x: Math.max(0, Math.min(1, x)),
      y: Math.max(0, Math.min(1, y)),
      angle: (id % 7 - 3) * 8,
      expires: now + (reducedMotion.current ? 500 : 1200),
    }
    setRipples((current) => [...current.filter((entry) => entry.expires > now), ripple].slice(-safeMax))
    if (announce) setStatus(`Ripple ${id + 1} made.`)
  }

  function addAtPoint(point: Point, announce = false) {
    const bounds = field.current?.getBoundingClientRect()
    if (!bounds || bounds.width <= 0 || bounds.height <= 0) return
    addRipple((point.x - bounds.left) / bounds.width, (point.y - bounds.top) / bounds.height, announce)
  }

  return (
