    const next = event.key === 'Home' ? 0 : event.key === 'End' ? items.length - 1 : current < 0 ? backward ? items.length - 1 : 0 : (current + (backward ? -1 : 1) + items.length) % items.length;
    links.current[next]?.focus();
  }

