  box-sizing: border-box;
  padding: 5px 5px 18px;
  background: var(--ac-trail-print-paper, #fffcf3);
  box-shadow: 0 5px 8px #1c251f16, 0 16px 28px #1c251f17;
  transform: translate(-50%, -50%) rotate(var(--ac-trail-rotation)) scale(var(--ac-trail-scale, 1));
  transform-origin: 50% 65%;
  animation: ac-trail-arrive var(--ac-trail-lifetime, 1400ms) both;
  will-change: transform, opacity;
}

.ac-trail-artwork {
  width: 100%;
  height: 100%;
  overflow: hidden;
  background: var(--ac-trail-print-background, #df623e);
}

.ac-trail-artwork > * {
  display: block;
  box-sizing: border-box;
