'use client';

import { useEffect, useMemo, useRef } from 'react';
import './elastic-type.css';

export interface ElasticTypeProps {
  text: string;
  as?: 'h1' | 'h2' | 'h3' | 'p';
  className?: string;
  /** Letter deformation, from 0 (still) to 2. */
  strength?: number;
  /** Pointer influence in pixels. */
  radius?: number;
}

type Vector = [number, number, number, number, number];
type Letter = {
  shell: HTMLElement;
  glyph: HTMLElement;
  x: number;
  y: number;
  size: number;
  value: Vector;
  velocity: Vector;
  target: Vector;
};

function graphemes(value: string): string[] {
  if (typeof Intl !== 'undefined' && 'Segmenter' in Intl) {
    const segmenter = new Intl.Segmenter(undefined, { granularity: 'grapheme' });
    return Array.from(segmenter.segment(value), (segment) => segment.segment);
  }
  // A small fallback keeps common combining marks, emoji modifiers, flags,
  // and joined emoji together without adding a segmentation dependency.
  const clusters: string[] = [];
  for (const point of Array.from(value)) {
    const previous = clusters[clusters.length - 1];
    const joinsPrevious = /\p{Mark}|[\uFE00-\uFE0F\u{1F3FB}-\u{1F3FF}\u{E0020}-\u{E007F}]/u.test(point)
      || point === '\u200D'
      || previous?.endsWith('\u200D')
      || (/^[\u{1F1E6}-\u{1F1FF}]$/u.test(point) && /^[\u{1F1E6}-\u{1F1FF}]$/u.test(previous ?? ''));
    if (previous && joinsPrevious) clusters[clusters.length - 1] += point;
    else clusters.push(point);
  }
  return clusters;
}

/** A readable phrase whose letterforms deform around a pointer and spring home. */
export function ElasticType({
  text,
  as: Element = 'p',
  className = '',
  strength = 1,
  radius = 150,
}: ElasticTypeProps) {
  const visualRef = useRef<HTMLSpanElement>(null);
  const parts = useMemo(
    () => text.split(/(\s+)/).map((part) => ({ text: part, characters: graphemes(part) })),
    [text],
  );
  const influence = Number.isFinite(strength) ? Math.min(2, Math.max(0, strength)) : 1;
  const reach = Number.isFinite(radius) ? Math.max(1, radius) : 150;

  useEffect(() => {
    const visual = visualRef.current;
    if (!visual) return;

    const letters: Letter[] = Array.from(
      visual.querySelectorAll<HTMLElement>('.ac-elastic-type__letter'),
      (shell) => ({
        shell,
        glyph: shell.firstElementChild as HTMLElement,
        x: 0,
        y: 0,
        size: 16,
        value: [0, 0, 0, 0, 0],
        velocity: [0, 0, 0, 0, 0],
        target: [0, 0, 0, 0, 0],
      }),
    );
    const motion = window.matchMedia('(prefers-reduced-motion: reduce)');
    const finePointer = window.matchMedia('(any-hover: hover) and (any-pointer: fine)');
    let frame = 0;
    let lastTime = 0;
    let alive = true;
    let inView = true;
    let hovering = false;
    let needsMeasure = true;
    let needsTargets = true;
    let pointerX = 0;
    let pointerY = 0;

    const enabled = () => !motion.matches && finePointer.matches && influence > 0 && inView;

    const clear = () => {
      window.cancelAnimationFrame(frame);
      frame = 0;
      lastTime = 0;
      for (const letter of letters) {
        letter.value.fill(0);
        letter.velocity.fill(0);
        letter.target.fill(0);
        letter.glyph.style.removeProperty('transform');
        letter.glyph.style.removeProperty('will-change');
      }
    };

    const measure = () => {
      // Shells remain at their natural positions while their children transform.
      // Read every rectangle before writing any animation styles.
      for (const letter of letters) {
        const rect = letter.shell.getBoundingClientRect();
        letter.x = rect.left + rect.width / 2;
        letter.y = rect.top + rect.height / 2;
        letter.size = rect.height;
      }
      needsMeasure = false;
    };

    const updateTargets = () => {
      for (const letter of letters) {
        if (!hovering) {
          letter.target.fill(0);
          continue;
        }
        const dx = (letter.x - pointerX) / reach;
        const dy = (letter.y - pointerY) / reach;
        const distance = Math.hypot(dx, dy);
        const force = Math.pow(Math.max(0, 1 - distance), 2) * influence;
        const side = Math.min(1, Math.abs(dx));
        letter.target = [
          dx * letter.size * 0.2 * force,
          -Math.min(40, letter.size * 0.3) * force + dy * letter.size * 0.08 * force,
          (0.34 - side * 0.62) * force,
          (-0.27 + side * 0.86) * force,
          dx * 13 * force,
        ];
      }
      needsTargets = false;
    };

    const animate = (time: number) => {
      frame = 0;
      if (!enabled()) {
        clear();
        return;
      }
      const step = lastTime ? Math.min(2, Math.max(0.25, (time - lastTime) / 16.667)) : 1;
      lastTime = time;
      if (needsMeasure) measure();
      if (needsTargets) updateTargets();
      let unsettled = false;

      for (const letter of letters) {
        let letterMoving = false;
        for (let index = 0; index < 5; index++) {
          const difference = letter.target[index] - letter.value[index];
          letter.velocity[index] = (letter.velocity[index] + difference * 0.14 * step) * Math.pow(0.67, step);
          letter.value[index] += letter.velocity[index] * step;
          const tolerance = index === 2 || index === 3 ? 0.0005 : 0.008;
          if (Math.abs(difference) + Math.abs(letter.velocity[index]) > tolerance) {
            letterMoving = true;
          } else {
            letter.value[index] = letter.target[index];
            letter.velocity[index] = 0;
          }
        }
        const [x, y, stretchX, stretchY, rotation] = letter.value;
        if (!letterMoving && letter.target.every((value) => value === 0)) {
          letter.glyph.style.removeProperty('transform');
          letter.glyph.style.removeProperty('will-change');
        } else {
          letter.glyph.style.transform = `translate3d(${x.toFixed(3)}px, ${y.toFixed(3)}px, 0) rotate(${rotation.toFixed(3)}deg) scale(${(1 + stretchX).toFixed(4)}, ${(1 + stretchY).toFixed(4)})`;
          if (letterMoving) letter.glyph.style.willChange = 'transform';
          else letter.glyph.style.removeProperty('will-change');
        }
        unsettled ||= letterMoving;
      }

      if (unsettled) frame = window.requestAnimationFrame(animate);
      else lastTime = 0;
    };

    const start = () => {
      if (!frame && enabled()) frame = window.requestAnimationFrame(animate);
    };
    const move = (event: PointerEvent) => {
      if (event.pointerType === 'touch' || !enabled()) return;
      hovering = true;
      pointerX = event.clientX;
      pointerY = event.clientY;
      needsMeasure = true;
      needsTargets = true;
      start();
    };
    const leave = () => {
      hovering = false;
      needsTargets = true;
      start();
    };
    const geometryChanged = () => {
      needsMeasure = true;
      needsTargets = true;
      if (hovering) start();
    };
    const preferenceChanged = () => {
      hovering = false;
      clear();
    };
    const visibilityChanged = () => {
      if (document.hidden) {
        hovering = false;
        clear();
      }
    };

    visual.addEventListener('pointerenter', move);
    visual.addEventListener('pointermove', move);
    visual.addEventListener('pointerleave', leave);
    visual.addEventListener('pointercancel', leave);
    window.addEventListener('scroll', geometryChanged, { capture: true, passive: true });
    window.addEventListener('resize', geometryChanged, { passive: true });
    window.addEventListener('blur', leave);
    document.addEventListener('visibilitychange', visibilityChanged);
    motion.addEventListener('change', preferenceChanged);
    finePointer.addEventListener('change', preferenceChanged);

    const resizeObserver = typeof ResizeObserver !== 'undefined' ? new ResizeObserver(geometryChanged) : undefined;
    resizeObserver?.observe(visual);
    const intersectionObserver = typeof IntersectionObserver !== 'undefined'
      ? new IntersectionObserver(([entry]) => {
        inView = entry.isIntersecting;
        if (!inView) {
          hovering = false;
          clear();
        } else {
          needsMeasure = true;
        }
      })
      : undefined;
    intersectionObserver?.observe(visual);
    document.fonts?.ready.then(() => {
      if (alive) geometryChanged();
    });

    return () => {
      alive = false;
      clear();
      resizeObserver?.disconnect();
      intersectionObserver?.disconnect();
      visual.removeEventListener('pointerenter', move);
      visual.removeEventListener('pointermove', move);
      visual.removeEventListener('pointerleave', leave);
      visual.removeEventListener('pointercancel', leave);
      window.removeEventListener('scroll', geometryChanged, true);
      window.removeEventListener('resize', geometryChanged);
      window.removeEventListener('blur', leave);
      document.removeEventListener('visibilitychange', visibilityChanged);
      motion.removeEventListener('change', preferenceChanged);
      finePointer.removeEventListener('change', preferenceChanged);
    };
  }, [Element, text, influence, reach]);

  return (
    <Element className={`ac-elastic-type ${className}`.trim()}>
      <span className="ac-elastic-type__accessible">{text}</span>
      <span ref={visualRef} className="ac-elastic-type__visual" aria-hidden="true">
        {parts.map((part, wordIndex) => /^\s*$/.test(part.text)
          ? part.text
          : (
            <span className="ac-elastic-type__word" key={wordIndex}>
              {part.characters.map((character, characterIndex) => (
                <span className="ac-elastic-type__letter" key={characterIndex}>
                  <span className="ac-elastic-type__glyph">{character}</span>
                </span>
              ))}
            </span>
          ))}
      </span>
    </Element>
  );
}

export default ElasticType;

.ac-elastic-type {
  position: relative;
  min-width: 0;
  max-width: 100%;
  color: inherit;
  overflow-wrap: anywhere;
}

.ac-elastic-type__accessible {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
  border: 0;
}

.ac-elastic-type__visual {
  display: block;
  white-space: pre-wrap;
}

.ac-elastic-type__word {
  display: inline-block;
  max-width: 100%;
  white-space: normal;
  vertical-align: baseline;
}

.ac-elastic-type__letter,
.ac-elastic-type__glyph {
  display: inline-block;
  vertical-align: baseline;
}

.ac-elastic-type__glyph {
  transform-origin: 50% 75%;
}

@media (prefers-reduced-motion: reduce), (hover: none) {
  .ac-elastic-type__glyph {
    transform: none !important;
    will-change: auto !important;
  }
}

'use client'

import { useEffect, useId, useRef, useState } from 'react'
import type { CSSProperties, PointerEvent, ReactNode } from 'react'
import './peel-reveal.css'

export interface PeelRevealProps {
  /** Decorative cover artwork. Keep links and other controls in children instead. */
  front: ReactNode
  /** Content uncovered by the paper. It becomes interactive once the peel opens. */
  children: ReactNode
  label?: string
  defaultOpen?: boolean
  className?: string
  onOpenChange?: (open: boolean) => void
}

type Point = { x: number; y: number }
type Drag = { pointerId: number; x: number; y: number; startProgress: number; moved: boolean }

function clipPaper(points: Point[], crease: number, front: boolean): Point[] {
  const clipped: Point[] = []
  for (let index = 0; index < points.length; index += 1) {
    const a = points[index]
    const b = points[(index + 1) % points.length]
    const aDistance = a.x + a.y - crease
    const bDistance = b.x + b.y - crease
    const aInside = front ? aDistance <= 0 : aDistance >= 0
    const bInside = front ? bDistance <= 0 : bDistance >= 0
    if (aInside) clipped.push(a)
    if (aInside !== bInside) {
      const amount = aDistance / (aDistance - bDistance)
      clipped.push({ x: a.x + (b.x - a.x) * amount, y: a.y + (b.y - a.y) * amount })
    }
  }
  return clipped
}

function polygon(points: Point[]) {
  return points.length >= 3
    ? `polygon(${points.map(({ x, y }) => `${x.toFixed(2)}px ${y.toFixed(2)}px`).join(', ')})`
    : 'polygon(0 0, 0 0, 0 0)'
}

/** A folded paper cover with a touch-safe drag corner and a keyboard alternative. */
export function PeelReveal({
  front,
  children,
  label = 'Peel to reveal',
  defaultOpen = false,
  className = '',
  onOpenChange,
}: PeelRevealProps) {
  const instanceId = useId()
  const rootRef = useRef<HTMLDivElement>(null)
  const frontRef = useRef<HTMLButtonElement>(null)
  const closeRef = useRef<HTMLButtonElement>(null)
  const progressRef = useRef(defaultOpen ? 1 : 0)
  const frameRef = useRef<number | null>(null)
  const dragRef = useRef<Drag | null>(null)
  const suppressClick = useRef(false)
  const reducedMotion = useRef(false)
  const animatingRef = useRef(false)
  const animationTarget = useRef<boolean | null>(null)
  const openRef = useRef(defaultOpen)
  const focusOnCommit = useRef(false)
  const callbackRef = useRef(onOpenChange)
  const [open, setOpen] = useState(defaultOpen)
  const [progress, setProgress] = useState(defaultOpen ? 1 : 0)
  const [dragging, setDragging] = useState(false)
  const [size, setSize] = useState({ width: 400, height: 360 })
  const [measured, setMeasured] = useState(false)

  useEffect(() => { callbackRef.current = onOpenChange }, [onOpenChange])

  useEffect(() => {
    if (!focusOnCommit.current) return
    focusOnCommit.current = false
    ;(open ? closeRef.current : frontRef.current)?.focus({ preventScroll: true })
  }, [open])

  useEffect(() => {
    const root = rootRef.current
    if (!root) return
    function measure() {
      if (!root) return
      setSize({ width: root.clientWidth, height: root.clientHeight })
      setMeasured(true)
    }
    measure()
    const observer = new ResizeObserver(measure)
    observer.observe(root)
    const media = window.matchMedia('(prefers-reduced-motion: reduce)')
    const updateMotion = () => {
      reducedMotion.current = media.matches
      if (media.matches && animatingRef.current && animationTarget.current !== null) {
        if (frameRef.current !== null) cancelAnimationFrame(frameRef.current)
        frameRef.current = null
        const target = animationTarget.current
        animationTarget.current = null
        animatingRef.current = false
        updateProgress(target ? 1 : 0)
        commitOpen(target, Boolean(root?.contains(document.activeElement)))
      }
    }
    updateMotion()
    media.addEventListener('change', updateMotion)
    return () => {
      observer.disconnect()
      media.removeEventListener('change', updateMotion)
      if (frameRef.current !== null) cancelAnimationFrame(frameRef.current)
    }
  }, [])

  function updateProgress(value: number) {
    progressRef.current = Math.min(1, Math.max(0, value))
    setProgress(progressRef.current)
  }

  function commitOpen(next: boolean, moveFocus: boolean) {
    if (openRef.current === next) return
    openRef.current = next
    focusOnCommit.current = moveFocus
    setOpen(next)
    callbackRef.current?.(next)
  }

  function settle(next: boolean) {
    if (frameRef.current !== null) cancelAnimationFrame(frameRef.current)
    const from = progressRef.current
    const target = next ? 1 : 0
    const focusInside = Boolean(rootRef.current?.contains(document.activeElement))
    const duration = reducedMotion.current ? 0 : 560 * Math.max(0.35, Math.abs(target - from))
    // Closing immediately removes the uncovered controls from the tab order.
    if (!next) commitOpen(false, focusInside)
    animatingRef.current = true
    animationTarget.current = next
    const startedAt = performance.now()
    function tick(time: number) {
      const elapsed = duration === 0 ? 1 : Math.min(1, (time - startedAt) / duration)
      const eased = 1 - (1 - elapsed) ** 3
      updateProgress(from + (target - from) * eased)
      if (elapsed < 1) {
        frameRef.current = requestAnimationFrame(tick)
      } else {
        frameRef.current = null
        animatingRef.current = false
        animationTarget.current = null
        if (next) commitOpen(true, focusInside)
      }
    }
    if (duration === 0) tick(startedAt)
    else frameRef.current = requestAnimationFrame(tick)
  }

  function startDrag(event: PointerEvent<HTMLButtonElement>) {
    if (!event.isPrimary || event.button !== 0 || openRef.current) return
    event.preventDefault()
    if (frameRef.current !== null) cancelAnimationFrame(frameRef.current)
    animatingRef.current = false
    animationTarget.current = null
    suppressClick.current = false
    frontRef.current?.focus({ preventScroll: true })
    event.currentTarget.setPointerCapture(event.pointerId)
    dragRef.current = { pointerId: event.pointerId, x: event.clientX, y: event.clientY, startProgress: progressRef.current, moved: false }
    setDragging(true)
  }

  function moveDrag(event: PointerEvent<HTMLButtonElement>) {
    const drag = dragRef.current
    if (!drag || drag.pointerId !== event.pointerId) return
    const x = drag.x - event.clientX
    const y = drag.y - event.clientY
    if (Math.hypot(x, y) > 5) drag.moved = true
    updateProgress(drag.startProgress + (x + y) / Math.max(1, size.width + size.height) * 1.5)
  }

  function endDrag(event: PointerEvent<HTMLButtonElement>, cancelled = false) {
    const drag = dragRef.current
    if (!drag || drag.pointerId !== event.pointerId) return
    dragRef.current = null
    setDragging(false)
    if (event.currentTarget.hasPointerCapture(event.pointerId)) {
      event.currentTarget.releasePointerCapture(event.pointerId)
    }
    // The synthetic click after a drag must not reverse its snap decision.
    suppressClick.current = drag.moved || cancelled
    if (drag.moved || cancelled) settle(!cancelled && progressRef.current >= 0.38)
  }

  const { width, height } = size
  const peek = Math.min(64, Math.max(44, Math.min(width, height) * 0.17))
  const crease = (width + height - peek) * (1 - progress) - 72 * progress
  const corners = [{ x: 0, y: 0 }, { x: width, y: 0 }, { x: width, y: height }, { x: 0, y: height }]
  // Before measurement, percentage-based clipping covers every SSR container size.
  // Keep the initial client render identical to the server-rendered markup.
  const emptyClip = 'polygon(0 0, 0 0, 0 0)'
  const frontClip = measured ? polygon(clipPaper(corners, crease, true)) : defaultOpen ? emptyClip : 'inset(0)'
  // Reflect the lifted paper across x + y = crease to produce the visible underside.
  const foldClip = measured ? polygon(clipPaper(corners, crease, false).map(({ x, y }) => ({ x: crease - y, y: crease - x }))) : emptyClip
  const style = {
    '--ac-peel-fold-stop': `${Math.max(0, crease / Math.max(1, width + height) * 100)}%`,
    '--ac-peel-handle-x': `${-progress * width * 0.65}px`,
    '--ac-peel-handle-y': `${-progress * height * 0.65}px`,
    '--ac-peel-handle-opacity': Math.max(0, 1 - progress * 4),
  } as CSSProperties

  return (
    <div
      className={`ac-peel-reveal ${className}`.trim()}
      ref={rootRef}
      data-open={open}
      data-dragging={dragging}
      style={style}
      onKeyDown={(event) => {
        if (event.key === 'Escape' && openRef.current) {
          event.preventDefault()
          event.stopPropagation()
          settle(false)
        }
      }}
    >
      <div
        className="ac-peel-content"
        id={`${instanceId}-content`}
        role="region"
        aria-label="Revealed content"
        aria-hidden={!open}
        ref={(element) => {
          // A DOM property avoids React 18's unknown-boolean-attribute warning.
          if (element) element.inert = !open
        }}
      >
        {children}
      </div>
      <div className="ac-peel-front" aria-hidden="true" style={{ clipPath: frontClip }}>
        <div className="ac-peel-artwork" ref={(element) => { if (element) element.inert = true }}>{front}</div>
      </div>
      <div className="ac-peel-fold-shadow" aria-hidden="true" style={{ clipPath: foldClip }} />
      <div className="ac-peel-fold" aria-hidden="true" style={{ clipPath: foldClip }} />
      <button
        className="ac-peel-trigger"
        type="button"
        ref={frontRef}
        tabIndex={open ? -1 : 0}
        aria-hidden={open}
        aria-label={label}
        aria-expanded={open}
        aria-controls={`${instanceId}-content`}
        aria-describedby={`${instanceId}-instruction`}
        style={{ clipPath: frontClip }}
        onClick={() => { if (!animatingRef.current) settle(true) }}
      />
      <button
        className="ac-peel-handle"
        type="button"
        aria-hidden="true"
        tabIndex={-1}
        hidden={open}
        onPointerDown={startDrag}
        onPointerMove={moveDrag}
        onPointerUp={(event) => endDrag(event)}
        onPointerCancel={(event) => endDrag(event, true)}
        onLostPointerCapture={(event) => endDrag(event, true)}
        onClick={() => {
          if (suppressClick.current) { suppressClick.current = false; return }
          if (!animatingRef.current) settle(true)
        }}
      >
        <svg width="20" height="20" viewBox="0 0 20 20" fill="none"><path d="M15 5 5 15m0 0V7m0 8h8" stroke="currentColor" strokeWidth="1.4" strokeLinecap="round" strokeLinejoin="round" /></svg>
      </button>
      <button className="ac-peel-close" type="button" ref={closeRef} hidden={!open} onClick={() => settle(false)}>
        <span aria-hidden="true">↘</span> Close peel
      </button>
      <span className="ac-peel-instruction" id={`${instanceId}-instruction`}>Pull the bottom-right corner inward, or activate the cover to reveal its contents.</span>
    </div>
  )
}

