  overflow: hidden;
  border: 1px solid var(--ac-card-border, rgb(255 255 255 / 12%));
  border-radius: var(--ac-card-radius, 16px);
  background: var(--ac-card-surface, #191b18);
  color: var(--ac-card-color, #e9e9df);
}

